<template>
    <div class="page">
        <app-header :title='tits' :istop="num"></app-header>
        <div class="main test hlcon">
            <div v-if="loading" class="loads">
                <van-loading size="20px" type="spinner"/>
            </div>
            <ul class="tabs">
                <li  @click="changeps(1)" 
                    :class="current == 1 ? 'active' : 'default'">会员降倍
                </li>
                <li   @click="changeps(2)" 
                    :class="current == 2 ? 'active' : 'default'">特殊会员降倍
                </li>
                <li  @click="changeps(3)" 
                    :class="current == 3 ? 'active' : 'default'">特殊会员名单
                </li>
            </ul>
            <div v-if="current <3"   class="tab-list-lot" @click="optabs">
                <div class="tab-list-lot-t">{{lotName}}</div>
                <img src="@/assets/images/yx_xla.webp">
            </div>
            <div  v-if="current <3"  class="men-t">
                <div class="men-t-1">
                    <van-field
                            class="input"
                            style="width:75px;margin-left: 5px;margin-right: 10px;height:25px;line-height:20px;"
                            type="number"
                            size="mini"
                            :border="true"
                            v-model="quickAmout"
                            placeholder="输入赔率"
                    />
                    <img v-if="quickStatus==1" @click="swTabs(2)" class="men1-img" src="@/assets/images/swqy.svg">
                    <img v-if="quickStatus==2" @click="swTabs(1)" class="men1-img" src="@/assets/images/swjy.svg">
                    <div  class="mbtns" @click="quickSet" >套用</div>
                </div>
                <div style="overflow:auto;padding-bottom:10px">
                    <table style="width:200%" >
                        <thead>
                            <tr>
                                <th rowspan="2">玩法</th>
                                <th colspan="2">第一阶段(一次性)</th>
                                <th colspan="2">第二阶段(累进)</th>
                                <th rowspan="2">最大降倍</th>
                            </tr>
                            <tr>
                                <th>金额(实货量)</th>
                                <th>降赔率</th>
                                <th>金额(实货量)</th>
                                <th>降赔率</th>
                            </tr>
                        </thead>
                        <tbody>
                            <tr v-for="(item,index2) in betmoneyodds_list" :key="index2" :class="(index2%2==0)?'eve':'old'">
                                <td style="height: 35px;line-height: 35px;">{{item.downOddsName}}</td>
                                <td >
                                    <van-stepper :show-minus="false" :show-plus="false" :min="0" integer  @keyup.native="check_count" v-model="item.firstDownAmount"></van-stepper>
                                </td>
                                <td >
                                    <van-stepper :show-minus="false" :show-plus="false" :min="0"   v-model="item.firstDownOdds"></van-stepper>
                                </td>
                                <td >
                                    <van-stepper :show-minus="false" :show-plus="false" :min="0"   @keyup.native="check_count" v-model="item.everyDownAmount"></van-stepper>
                                </td>
                                <td >
                                    <van-stepper :show-minus="false" :show-plus="false" :min="0"    v-model="item.everyDownOdds"></van-stepper>
                                </td>
                                <td >
                                    <van-stepper :show-minus="false" :show-plus="false" :min="0"    v-model="item.maxDown"></van-stepper>
                                </td>
                            </tr>
                        </tbody>
                    </table>
                </div>
            </div>
            <div class="men-t2" v-if="current == 3">
                <div  class="mbtns" style="margin-top:5px;margin-left: 5px;" @click="addGanes">增加会员</div>
                <table style="margin-top: 5px">
                    <thead>
                        <tr>
                            <th>会员账号</th>
                            <th>额度</th>
                            <th>操作</th>
                        </tr>
                    </thead>
                    <tbody v-if="menberList.length>0">
                        <tr v-for="(item,index2) in menberList" :key="index2+1">
                            <td>{{item.account }}</td>
                            <td>{{item.cash}}</td>
                            <td>
                                <span @click="handleDeleteMember(item)" class="blue">删除</span>
                            </td>
                        </tr>
                    </tbody>
                </table>
            </div>
            <div class="zdbh-btns"  v-if="current!=3" >
                <div @click="savebetmoney" class="zdbh-btns-sub">确定</div>
            </div>
        </div>
        <van-popup v-model:show="showLottery" position="bottom" class="popTop" >
            <div class="pop-list">
              <div class="pop-line">
                <div class="pop-lines">
                  <div class="pop-list-line"></div>
                </div>
                <div class="pop-head">
                  <div class="pop-head-t">彩种选择</div>
                  <div @click="showLottery=false" class="pop-head-img">关闭</div>
                </div>
              </div>
              <div class="pop-cont">
                <div class="flex-item">
                  <div class="yx-select" @click="onConfirm(item)" :class="lotId==item.id?'active':''" v-for="item in lotList" :key="item.id">{{item.name}}</div>
                </div> 
              </div>
            </div>
        </van-popup>
        <van-popup v-model:show="mShow" :overlay="false" position="bottom" class="popTop">
          <div class="pop-list">
            <div class="pop-line">
                <div class="pop-lines">
                  <div class="pop-list-line"></div>
                </div>
                <div class="pop-head">
                  <div class="pop-head-t">添加会员名单</div>
                  <div @click="mShow=false" class="pop-head-img">关闭</div>
                </div>
              </div>
            <div style="padding: 10px">
                <div class="add-men">
                    <div class="add-men-t">会员账号</div>
                    <div class="add-men-i">
                        <van-field v-model="memberForm.account"
                                        class="input" size="mini" style="width:160px;margin: 0 auto;"></van-field>
                    </div>
                </div>
                <div class="fobtn">
                    <div class="fobcanl" @click="mShow=false">取消</div>
                    <div class="fobmits"  @click="AddMemberSubmit" >确定</div>
                </div>
            </div>
          </div>
        </van-popup>
    </div>
</template>
<script setup lang="ts">
import { ref, reactive, onMounted } from 'vue'
import { useRouter,useRoute } from 'vue-router'
import { useUserStore } from '@/store/user'
import { useAppStore } from '@/store/index'
import { useTimeUtils } from '@/utils/time'
import useMd5 from '@/utils/useMd5'
import { showToast, showConfirmDialog,showLoadingToast } from 'vant'
import nzhcn from "nzh/cn";

// 路由和状态管理
const router = useRouter()
const route = useRoute()
const userStore = useUserStore()
const appStore = useAppStore()
const userTime = useTimeUtils()
const betmoneyodds_list = ref([])
const loading = ref(false)
const quickAmout = ref("")
const quickStatus = ref('2')
const lotList = ref([])
const lotName = ref('')
const lotId = ref('')
const num = ref(3)
const tits = ref('会员降倍')
const current = ref(1)
const showLottery = ref(false)
const menberList = ref([])
const memFormRef = ref('')
const memberForm = ref({
  breakStatus:1,
  account: ''
})
const mShow = ref(false)
const transferMoney = ref('') // 补充定义，用于check_count
// Methods
const optabs = () => {
  showLottery.value = true
}
const onConfirm = (its) => {
  lotName.value = its.name
  lotId.value = its.id
  showLottery.value = false
  getbetmoney()
}
const getLot = async () => {
  try {
    const res = await userStore.getLotList()
    lotList.value = res.data
    lotId.value = res.data[0].id
    lotName.value = res.data[0].name
    await getbetmoney()
  } catch (error) {
    console.error('获取彩种失败:', error)
  }
}
const check_count = (e) => {
  let obj = e.target
  if (obj.value != '' && obj.value.substr(0, 1) == '.') {
    obj.value = 0
  }
  if (!obj.value) {
    obj.value = 0
  }
  obj.value = obj.value.replace(/^0*(0\.|[1-9])/, '$1')
  obj.value = obj.value.replace(/^(\-)*(\d+)\.(\d\d\d\d).*$/, '$1$2.$3')
  if (obj.value.indexOf(".") < 0 && obj.value != "") {
    if (obj.value.substr(0, 1) == '0' && obj.value.length == 2) {
      obj.value = obj.value.substr(1, obj.value.length)
    }
  }
  transferMoney.value = obj.value
}
const swTabs = async(num) => {
    quickStatus.value = num
    let type = '';
    let str = {
        lotteryId:lotId.value,
        downOddsType:current.value==1?4:5,
        openFlag:num
    }
    try {
        loading.value = true
        const res = await userStore.setDwonMkOpenFlag(str);
        loading.value = false
        getbetmoney()
    } catch (error) {
        loading.value = false
        console.log('获取游戏信息失败')
    } 
}

const ktswTabs = (item, num) => {
  item.status = num
}

const zstabs = (item) => {
  item.selected = !item.selected
}

const quickSet = () => {
  betmoneyodds_list.value.forEach(item => {
    item.firstDownOdds  = quickAmout.value
    item.everyDownOdds  = quickAmout.value
  })
}
const changeps = (obj) =>{
    current.value = obj;
    if (current.value  < 3 ) {
        getbetmoney();
    }
    if (current.value  == 3) {
       getMnebers();
    }
}
const getbetmoney = async () => {
  loading.value = true
  try {
    let str = {
        lotteryId:lotId.value,
        downOddsType:current.value==1?4:5,
    }
    const res = await userStore.queryMkDownOdds(str)
    res.data.map(iten => {
      iten.selected = true
    })
    betmoneyodds_list.value = res.data
  } catch (error) {
    console.error('获取赔率设置失败:', error)
  } finally {
    loading.value = false
  }
}

const savebetmoney = async () => {
  try {
    const res = await userStore.downMkOddsSave(betmoneyodds_list.value)
    // 假设您有一个toast组件或方法
    if (res.code == 200) {
      // 成功提示
      console.log('保存成功:', res.message)
      await getbetmoney()
    } else {
      // 失败提示
      console.error('保存失败:', res.message)
    }
  } catch (error) {
    console.error('保存赔率设置失败:', error)
  }
}
const addGanes = () =>{ //添加游戏
    reset();
    mShow.value = true;
}
const reset = () =>{
    memberForm.value = {
        breakStatus: 1,
        account: '',
    }
}
// 获取特殊会员列表
const getMnebers = async ()=> {
  try {
    const res = await userStore.breakInfo()
    menberList.value = res.data || []
  } catch (error) {
    console.error('获取会员列表失败:', error)
    menberList.value = []
  }
}
// 添加会员
const AddMemberSubmit = async () => {
  if (! memberForm.value.account) return
  try {
    memberForm.value.breakStatus = 1
    const res = await userStore.menSetBreak(memberForm.value)
    showToast({
        message: '添加会员成功',
        className: 'custom-toast',
        duration: 1000  // 自定义显示时间
    });
    mShow.value = false
    await getMnebers()
  } catch (error) {
    if (error instanceof Error && error.name !== 'ValidationError') {
      console.error('添加会员失败:', error)
    }
  }
}
// 删除会员
const handleDeleteMember = async (member)=> {
  try {
    await showConfirmDialog({
        title: `此操作将删除会员 "${member.account}"，是否继续?`,
        messageAlign: 'center',  // 设置 message 居中
        width: '85vw',  
    })
    const formData = {
      breakStatus: 2,
      account: member.account
    }
    
    const res = await userStore.menSetBreak(formData)
    showToast({
        message: '删除会员成功',
        className: 'custom-toast',
        duration: 1000  // 自定义显示时间
    });
    await getMnebers()
  } catch (error) {
    // 用户取消操作，不做处理
    if (error !== 'cancel') {
      console.error('删除会员失败:', error)
      console.log('删除失败')
    }
  }
}
// Lifecycle
onMounted(() => {
  getLot()
})
</script>
<style lang="less" scoped>
.hlcon :deep(.van-stepper__input){
    width:80px !important;
    height: 35px !important;
    line-height: 35px !important;
    background: #FFFFFF 0% 0% no-repeat padding-box;
    border: 1px solid #D0D0D0;
    border-radius: 10px;
    font-size: 16px;
}
