   color: var(--blue-normal);
}
.tab-list-lot{
    width: 85%;
    height: 40px;
    line-height: 40px;
    border: solid 0.3px var(--grey-blue-surface-g-50);
    background-color: var(--white-white);
    border-radius: 10px;
    margin: 0 auto;
    margin-top:10px;
    font-size: 16px;
    font-weight: normal;
    line-height: 40px;
    letter-spacing: 0px;
    color: var(--grey-blue-surface-g-700);
    display: flex;
    align-items: center;
    cursor: pointer;
    margin-bottom: 10px;
    .tab-list-lot-t{
        flex: 1;
        margin-left: 20px;
    }
    img{
        width: 20px;
        height: 20px;
        margin-right: 15px;
    }
}
.add-men{
   display:flex;
   align-items:center;
   height:50px;
}
.add-men-t{
  width:120px;
  font-size: 16px;
  font-weight: normal;
  color:#697089;
  text-align:center;
}
</style>